import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=id=>document.getElementById(id);
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x101b19); scene.fog=new THREE.Fog(0x101b19,28,76);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,120);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});
renderer.setSize(innerWidth,innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.2; document.body.prepend(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc3e6dc,0x293329,2.1));
const sun=new THREE.DirectionalLight(0xffe6b6,3.2); sun.position.set(-12,22,9); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-28;sun.shadow.camera.right=28;sun.shadow.camera.top=28;sun.shadow.camera.bottom=-28; scene.add(sun);
const fill=new THREE.PointLight(0x7affd9,32,28,2);fill.position.set(0,7,0);scene.add(fill);
const mat=(color,rough=.7,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const M={ground:mat(0x27342d),dark:mat(0x18231f,.7,.35),armor:mat(0x69785d,.44,.55),lime:mat(0xd8ff47,.32,.4),metal:mat(0x35423c,.4,.72),black:mat(0x101715,.35,.55),red:mat(0xf05a45,.4,.25),eye:mat(0x7dffed,.22,.3),enemy:mat(0x9b4432,.48,.35),gold:mat(0xffc15a,.35,.5)};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(200,200),M.ground);ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);
const grid=new THREE.GridHelper(100,50,0x687b50,0x455448);grid.position.y=.018;grid.material.transparent=true;grid.material.opacity=.27;scene.add(grid);
// Barren terrain plates, angular rocks and dead antennae make the arena feel authored without external assets.
let seed=731;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
for(let i=0;i<55;i++){let x=(rand()-.5)*72,z=(rand()-.5)*72;if(Math.hypot(x,z)<11)continue;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.35+rand()*1.25,0),i%4?mat(0x39453b):mat(0x665b43));rock.position.set(x,.12,z);rock.scale.y=.35+rand()*.65;rock.rotation.set(rand()*2,rand()*3,rand()*2);rock.castShadow=true;rock.receiveShadow=true;scene.add(rock)}
for(let i=0;i<12;i++){let a=i*Math.PI/6,r=22+rand()*8,x=Math.cos(a)*r,z=Math.sin(a)*r;const pole=new THREE.Group();pole.position.set(x,0,z);let p=new THREE.Mesh(new THREE.CylinderGeometry(.055,.11,2.2,5),M.dark);p.position.y=1.1;p.rotation.z=(rand()-.5)*.25;p.castShadow=true;pole.add(p);let lamp=new THREE.Mesh(new THREE.SphereGeometry(.12,8,6),M.red);lamp.position.set(.2,2.1,0);pole.add(lamp);scene.add(pole)}
const player=new THREE.Group();scene.add(player);const mech=new THREE.Group();player.add(mech);
function box(parent,w,h,d,material,pos,rot){let o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);o.position.set(...pos);if(rot)o.rotation.set(...rot);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function cyl(parent,r1,r2,h,material,pos,axis='y'){let o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,8),material);o.position.set(...pos);if(axis==='x')o.rotation.z=Math.PI/2;if(axis==='z')o.rotation.x=Math.PI/2;o.castShadow=true;parent.add(o);return o}
// Body shell, cockpit, sensor and twin shoulder cannons.
box(mech,1.1,.62,1.42,M.armor,[0,1.1,0]);box(mech,.82,.22,.75,M.lime,[0,1.46,-.08]);box(mech,.62,.48,.58,M.dark,[0,1.55,.18]);
const canopy=new THREE.Mesh(new THREE.BoxGeometry(.37,.2,.34),M.eye);canopy.position.set(0,1.68,.22);mech.add(canopy);
for(const s of [-1,1]){box(mech,.42,.55,.72,M.metal,[s*.72,1.08,-.13]);box(mech,.3,.28,.84,M.armor,[s*.73,1.42,-.22]);cyl(mech,.115,.115,.8,M.black,[s*.73,1.48,-.77],'z');cyl(mech,.15,.13,.16,M.gold,[s*.73,1.48,-1.16],'z');box(mech,.22,.32,.2,M.lime,[s*.72,1.13,.37]);}
// articulated legs with pistons and feet
const legs=[];for(const s of [-1,1]){let leg=new THREE.Group();leg.position.set(s*.39,.92,.16);mech.add(leg);box(leg,.32,.68,.38,M.armor,[0,-.27,.02]);cyl(leg,.09,.09,.62,M.dark,[s*.11,-.28,.08],'x');box(leg,.43,.22,.57,M.black,[0,-.63,.18]);box(leg,.3,.09,.34,M.lime,[0,-.5,.18]);legs.push(leg)}
const cannon=new THREE.Group();cannon.position.set(0,1.15,.85);mech.add(cannon);cyl(cannon,.13,.17,.9,M.metal,[0,0,.4],'z');cyl(cannon,.19,.19,.15,M.lime,[0,0,.86],'z');cyl(cannon,.12,.17,.25,M.black,[0,0,.95],'z');
player.position.set(0,0,0);
const clock=new THREE.Clock(),raycaster=new THREE.Raycaster(),mouseN=new THREE.Vector2(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0),aimPoint=new THREE.Vector3(0,0,8);
const bullets=[],enemies=[],pickups=[],effects=[];let keys={},mouseDown=false,started=false,paused=false,dead=false,upgrading=false;
let hp=100,maxHp=100,damage=12,fireRate=.145,fireClock=0,speed=7.6,bulletSpeed=32,magnet=1.2,armor=0,level=1,xp=0,xpNeed=8,kills=0,scrap=0,wave=1,spawnClock=0,waveClock=0,waveDuration=34,spawned=0,upgradeDeck=[],shotPulse=0;
const bulletMat=new THREE.MeshBasicMaterial({color:0xd9ff56});
const ui={hp:$('hpText'),hpBar:$('hpBar'),xp:$('xpText'),xpBar:$('xpBar'),wave:$('wave'),waveSub:$('waveSub'),kills:$('kills'),scrap:$('scrap'),toast:$('toast')};
const show=(id,on)=>$(id).classList.toggle('hidden',!on);
function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function updateUI(){ui.hp.textContent=`${Math.ceil(hp)} / ${maxHp}`;ui.hpBar.style.width=`${Math.max(0,hp/maxHp*100)}%`;ui.hpBar.style.background=hp/maxHp<.3?'#ff594e':'var(--lime)';ui.xp.textContent=`LV ${String(level).padStart(2,'0')} · ${xp} / ${xpNeed}`;ui.xpBar.style.width=`${xp/xpNeed*100}%`;ui.wave.textContent=String(wave).padStart(2,'0');ui.waveSub.textContent=waveClock<0?`SECTOR ${wave} SECURED`:`${Math.max(0,enemies.length)} HOSTILES ACTIVE`;ui.kills.textContent=String(kills).padStart(2,'0');ui.scrap.textContent=String(scrap).padStart(3,'0');$('weaponName').textContent=damage>22?'HEAVY PLASMA CANNON':'20MM RAPID CANNON';$('weaponSub').textContent=`${damage} DMG · ${(1/fireRate).toFixed(1)} ROUNDS/S`}
function makeEnemy(type){let group=new THREE.Group(),scale=1,hpVal=1,spd=1,hit=8,xpVal=1,color=M.enemy;
 if(type==='runner'){scale=.78;hpVal=24+wave*3;spd=2.65;hit=6;xpVal=1}
 else if(type==='tank'){scale=1.35;hpVal=90+wave*12;spd=.82;hit=15;xpVal=3;color=M.dark}
 else if(type==='drone'){scale=.82;hpVal=28+wave*4;spd=1.55;hit=8;xpVal=2;color=M.gold}
 else {hpVal=42+wave*6;spd=1.35;hit=10;xpVal=2}
 // A snarling, plated mechanical beast silhouette.
 box(group,.62,.48,1.04,color,[0,.72,0]);box(group,.53,.42,.53,M.dark,[0,.92,.55]);box(group,.43,.28,.38,M.enemy,[0,1.03,.82]);
 const eyes=new THREE.Mesh(new THREE.BoxGeometry(.28,.11,.08),M.red);eyes.position.set(0,1.08,1.03);group.add(eyes);
 for(const s of [-1,1]){box(group,.2,.32,.22,M.metal,[s*.3,.86,.63]);let leg=box(group,.19,.54,.2,M.dark,[s*.27,.33,.2]);leg.rotation.x=-.25;box(group,.18,.52,.2,M.dark,[s*.27,.31,-.34]);box(group,.18,.25,.58,color,[s*.28,1.0,-.3]);}
 // spines on rear armor
 for(let n=0;n<3;n++){let spine=new THREE.Mesh(new THREE.ConeGeometry(.12,.42,5),M.gold);spine.position.set(0,1.13,-.25-n*.22);spine.rotation.x=-.2;group.add(spine)}
 if(type==='drone'){group.clear();let orb=new THREE.Mesh(new THREE.IcosahedronGeometry(.47,1),M.gold);orb.position.y=1.55;orb.castShadow=true;group.add(orb);let ring=new THREE.Mesh(new THREE.TorusGeometry(.68,.045,6,16),M.red);ring.rotation.x=Math.PI/2;ring.position.y=1.55;group.add(ring);let eye=new THREE.Mesh(new THREE.SphereGeometry(.13,8,6),M.red);eye.position.set(0,1.55,.42);group.add(eye)}
 if(type==='boss'){scale=1.85;hpVal=440+wave*45;spd=.82;hit=24;xpVal=12;color=M.red;group.scale.setScalar(1.3)}
 group.scale.multiplyScalar(scale);group.position.y=0;scene.add(group);return {group,type,hp:hpVal,maxHp:hpVal,speed:spd,damage:hit,xp:xpVal,attack:0,phase:rand()*8,scale};
}
function spawnEnemy(){let a=rand()*Math.PI*2,r=19+rand()*5,pos=new THREE.Vector3(player.position.x+Math.cos(a)*r,0,player.position.z+Math.sin(a)*r);let type='wolf';let roll=rand();if(wave>=2&&roll<.32)type='runner';if(wave>=3&&roll<.23)type='drone';if(wave>=4&&roll<.16)type='tank';if(wave%5===0&&spawned===0)type='boss';let e=makeEnemy(type);e.group.position.copy(pos);enemies.push(e);spawned++}
function fire(){const geo=new THREE.SphereGeometry(.105,8,6),obj=new THREE.Mesh(geo,bulletMat);const dir=new THREE.Vector3(aimPoint.x-player.position.x,0,aimPoint.z-player.position.z).normalize();obj.position.set(player.position.x+dir.x*.95,1.22,player.position.z+dir.z*.95);scene.add(obj);bullets.push({mesh:obj,vel:dir.multiplyScalar(bulletSpeed),life:1.45,damage});shotPulse=.06}
function burst(pos,color=0xd8ff47,count=7){for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.055+rand()*.07,6,5),new THREE.MeshBasicMaterial({color,transparent:true}));m.position.copy(pos);scene.add(m);let v=new THREE.Vector3(rand()-.5,rand()*.8,rand()-.5).multiplyScalar(3+rand()*5);effects.push({mesh:m,vel:v,life:.45+rand()*.35})}}
function makePickup(pos,value){let g=new THREE.Group(),crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.23,0),M.eye);crystal.position.y=.42;crystal.castShadow=true;g.add(crystal);let ring=new THREE.Mesh(new THREE.TorusGeometry(.29,.025,5,14),M.lime);ring.rotation.x=Math.PI/2;g.add(ring);g.position.copy(pos);scene.add(g);pickups.push({group:g,value,phase:rand()*8})}

const upgrades=[
 {name:'OVERCHARGED CELLS',desc:'Increase cannon damage by 35%. Hostile armor is only a suggestion.',apply:()=>damage=Math.round(damage*1.35)},
 {name:'CYCLIC FEED',desc:'Increase weapon fire rate by 22%. More lead in the air.',apply:()=>fireRate=Math.max(.065,fireRate*.78)},
 {name:'REINFORCED PLATING',desc:'Increase maximum armor by 25 and repair 35 integrity.',apply:()=>{maxHp+=25;hp=Math.min(maxHp,hp+35)}},
 {name:'SERVO OVERDRIVE',desc:'Increase movement speed by 16%. Keep ahead of the pack.',apply:()=>speed*=1.16},
 {name:'SALVAGE MAGNET',desc:'Pull combat data from 45% farther away.',apply:()=>magnet*=1.45},
 {name:'PENETRATOR ROUNDS',desc:'Projectiles travel faster and hit through reinforced plating.',apply:()=>{bulletSpeed*=1.38;damage+=3}},
 {name:'FIELD REPAIR',desc:'Restore 45 armor integrity immediately.',apply:()=>hp=Math.min(maxHp,hp+45)},
 {name:'TARGETING ARRAY',desc:'Improve cannon calibration: +20% damage and faster fire cycle.',apply:()=>{damage=Math.round(damage*1.2);fireRate=Math.max(.065,fireRate*.91)}}
];
function openUpgrade(){upgrading=true;mouseDown=false;paused=false;const shuffled=[...upgrades].sort(()=>rand()-.5).slice(0,3);$('upLevel').textContent=String(level+1).padStart(2,'0');$('cards').innerHTML='';shuffled.forEach((u,i)=>{const card=document.createElement('div');card.className='card';card.innerHTML=`<div class="num">SYSTEM ${String(i+1).padStart(2,'0')}</div><h3>${u.name}</h3><p>${u.desc}</p><div class="pick">INSTALL ↗</div>`;card.onclick=()=>{u.apply();level++;xp-=xpNeed;xpNeed=Math.round(8*Math.pow(1.38,level-1));upgrading=false;show('upgradeScreen',false);updateUI();toast(`${u.name} INSTALLED`);if(xp>=xpNeed){openUpgrade()}};$('cards').appendChild(card)});show('upgradeScreen',true)}
function addXP(n){xp+=n;scrap+=n*3;while(xp>=xpNeed&&!upgrading){openUpgrade();break}}
function resetGame(){for(const a of [bullets,enemies,pickups,effects]){for(const o of a){let obj=o.mesh||o.group;if(obj)scene.remove(obj)}a.length=0}hp=100;maxHp=100;damage=12;fireRate=.145;fireClock=0;speed=7.6;bulletSpeed=32;magnet=1.2;armor=0;level=1;xp=0;xpNeed=8;kills=0;scrap=0;wave=1;spawnClock=1.3;waveClock=0;waveDuration=34;spawned=0;dead=false;paused=false;upgrading=false;started=true;player.position.set(0,0,0);mech.rotation.set(0,0,0);show('titleScreen',false);show('gameoverScreen',false);show('pauseScreen',false);show('upgradeScreen',false);$('hud').style.display='block';updateUI();toast('UNIT LZ-04 DEPLOYED')}
$('startBtn').addEventListener('click',resetGame);$('retryBtn').addEventListener('click',resetGame);$('resumeBtn').addEventListener('click',()=>{paused=false;show('pauseScreen',false)});
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&started&&!dead&&!upgrading){paused=!paused;show('pauseScreen',paused);mouseDown=false}});
addEventListener('keyup',e=>keys[e.code]=false);addEventListener('blur',()=>{keys={};mouseDown=false});
addEventListener('pointermove',e=>{mouseN.x=e.clientX/innerWidth*2-1;mouseN.y=-(e.clientY/innerHeight)*2+1});
addEventListener('pointerdown',e=>{if(e.button===0&&started&&!paused&&!upgrading&&!dead)mouseDown=true});addEventListener('pointerup',()=>mouseDown=false);addEventListener('contextmenu',e=>e.preventDefault());
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
function gameOver(){dead=true;mouseDown=false;show('gameoverScreen',true);$('finalStats').textContent=`${kills} HOSTILES / ${scrap} SCRAP · SECTOR ${wave}`}
function update(dt,time){if(!started||paused||dead||upgrading)return;
 // Cursor ray is intersected with the battle plane for direct, predictable aim.
 raycaster.setFromCamera(mouseN,camera);const hit=new THREE.Vector3();if(raycaster.ray.intersectPlane(groundPlane,hit))aimPoint.copy(hit);
 const move=new THREE.Vector3((keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),0,(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0));if(move.lengthSq()>0){move.normalize();player.position.addScaledVector(move,speed*dt)}
 const face=new THREE.Vector3(aimPoint.x-player.position.x,0,aimPoint.z-player.position.z);if(face.lengthSq()>.1)mech.rotation.y=Math.atan2(face.x,face.z);mech.position.y=Math.sin(time*10)*.025*(move.lengthSq()?1:0);legs.forEach((l,i)=>{l.rotation.x=move.lengthSq()?Math.sin(time*11+i*Math.PI)*.17:Math.sin(time*2+i)*.025});cannon.rotation.y=mech.rotation.y;
 const edge=44;player.position.x=THREE.MathUtils.clamp(player.position.x,-edge,edge);player.position.z=THREE.MathUtils.clamp(player.position.z,-edge,edge);
 const camTarget=new THREE.Vector3(player.position.x,0,player.position.z);const camPos=new THREE.Vector3(player.position.x,23,player.position.z+22);camera.position.lerp(camPos,1-Math.exp(-dt*3.2));camera.lookAt(player.position.x,0,player.position.z);
 fireClock-=dt;if(mouseDown&&fireClock<=0){fire();fireClock=fireRate}
 for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.mesh.position.addScaledVector(b.vel,dt);b.life-=dt;let hitEnemy=-1;for(let j=0;j<enemies.length;j++){let e=enemies[j];if(b.mesh.position.distanceTo(new THREE.Vector3(e.group.position.x,1,e.group.position.z))<e.scale*.95){hitEnemy=j;break}}
 if(hitEnemy>=0){let e=enemies[hitEnemy];e.hp-=b.damage;burst(b.mesh.position,0xffd35a,3);scene.remove(b.mesh);bullets.splice(i,1);if(e.hp<=0){const pos=e.group.position.clone();pos.y=.3;scene.remove(e.group);enemies.splice(hitEnemy,1);burst(pos,e.type==='boss'?0xff594e:0xd8ff47,13);makePickup(pos,e.xp);kills++;scrap+=e.type==='boss'?25:0;updateUI()}continue}if(b.life<=0){scene.remove(b.mesh);bullets.splice(i,1)}}
 spawnClock-=dt;waveClock+=dt;const maxAlive=Math.min(8+wave*2,22);if(waveClock<waveDuration&&spawnClock<=0&&enemies.length<maxAlive){spawnEnemy();spawnClock=Math.max(.25,1.15-wave*.055)*(0.65+rand()*.65)}
 if(waveClock>=waveDuration&&enemies.length===0){wave++;waveClock=0;spawned=0;waveDuration=34;spawnClock=2.2;toast(`SECTOR ${wave} — HOSTILES INBOUND`);updateUI()}
 for(const e of enemies){const g=e.group;const dx=player.position.x-g.position.x,dz=player.position.z-g.position.z,dist=Math.hypot(dx,dz)||.001;e.attack-=dt;e.phase+=dt*4;g.rotation.y=Math.atan2(dx,dz);if(e.type==='drone'){g.position.y=1.1+Math.sin(time*3+e.phase)*.24}
 if(dist>1.5){let v=(e.speed*(e.type==='runner'?1.25:1));g.position.x+=dx/dist*v*dt;g.position.z+=dz/dist*v*dt;g.position.y+=Math.sin(time*8+e.phase)*.006}else if(e.attack<=0){e.attack=e.type==='boss'?.65:1.05;hp-=Math.max(1,e.damage-armor);burst(new THREE.Vector3(player.position.x,1,player.position.z),0xff594e,2);if(hp<=0){hp=0;updateUI();gameOver()}}}
 for(let i=pickups.length-1;i>=0;i--){let p=pickups[i],g=p.group;g.rotation.y+=dt*1.4;g.position.y=.08+Math.sin(time*3+p.phase)*.12;let dx=player.position.x-g.position.x,dz=player.position.z-g.position.z,d=Math.hypot(dx,dz);if(d<magnet){g.position.x+=dx*dt*4;g.position.z+=dz*dt*4}if(d<.8){addXP(p.value);scene.remove(g);pickups.splice(i,1);updateUI()}}
 for(let i=effects.length-1;i>=0;i--){let e=effects[i];e.mesh.position.addScaledVector(e.vel,dt);e.vel.y-=5*dt;e.life-=dt;e.mesh.material.opacity=Math.max(0,e.life);if(e.life<=0){scene.remove(e.mesh);effects.splice(i,1)}}
 updateUI();
}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04),t=clock.elapsedTime;update(dt,t);renderer.render(scene,camera)}
// Camera is staged before deployment so the title screen already previews the play space.
camera.position.set(0,23,22);camera.lookAt(0,0,0);animate();

const upgrades=[
 {name:'OVERCHARGED CELLS',desc:'Increase cannon damage by 35%. Hostile armor is only a suggestion.',apply:()=>damage=Math.round(damage*1.35)},
 {name:'CYCLIC FEED',desc:'Increase weapon fire rate by 22%. More lead in the air.',apply:()=>fireRate=Math.max(.065,fireRate*.78)},
 {name:'REINFORCED PLATING',desc:'Increase maximum armor by 25 and repair 35 integrity.',apply:()=>{maxHp+=25;hp=Math.min(maxHp,hp+35)}},
 {name:'SERVO OVERDRIVE',desc:'Increase movement speed by 16%. Keep ahead of the pack.',apply:()=>speed*=1.16},
 {name:'SALVAGE MAGNET',desc:'Pull combat data from 45% farther away.',apply:()=>magnet*=1.45},
 {name:'PENETRATOR ROUNDS',desc:'Projectiles travel faster and hit through reinforced plating.',apply:()=>{bulletSpeed*=1.38;damage+=3}},
 {name:'FIELD REPAIR',desc:'Restore 45 armor integrity immediately.',apply:()=>hp=Math.min(maxHp,hp+45)},
 {name:'TARGETING ARRAY',desc:'Improve cannon calibration: +20% damage and faster fire cycle.',apply:()=>{damage=Math.round(damage*1.2);fireRate=Math.max(.065,fireRate*.91)}}
];
function openUpgrade(){upgrading=true;mouseDown=false;paused=false;const shuffled=[...upgrades].sort(()=>rand()-.5).slice(0,3);$('upLevel').textContent=String(level+1).padStart(2,'0');$('cards').innerHTML='';shuffled.forEach((u,i)=>{const card=document.createElement('div');card.className='card';card.innerHTML=`<div class="num">SYSTEM ${String(i+1).padStart(2,'0')}</div><h3>${u.name}</h3><p>${u.desc}</p><div class="pick">INSTALL ↗</div>`;card.onclick=()=>{u.apply();level++;xp-=xpNeed;xpNeed=Math.round(8*Math.pow(1.38,level-1));upgrading=false;show('upgradeScreen',false);updateUI();toast(`${u.name} INSTALLED`);if(xp>=xpNeed){openUpgrade()}};$('cards').appendChild(card)});show('upgradeScreen',true)}
function addXP(n){xp+=n;scrap+=n*3;while(xp>=xpNeed&&!upgrading){openUpgrade();break}}
function resetGame(){for(const a of [bullets,enemies,pickups,effects]){for(const o of a){let obj=o.mesh||o.group;if(obj)scene.remove(obj)}a.length=0}hp=100;maxHp=100;damage=12;fireRate=.145;fireClock=0;speed=7.6;bulletSpeed=32;magnet=1.2;armor=0;level=1;xp=0;xpNeed=8;kills=0;scrap=0;wave=1;spawnClock=1.3;waveClock=0;waveDuration=34;spawned=0;dead=false;paused=false;upgrading=false;started=true;player.position.set(0,0,0);mech.rotation.set(0,0,0);show('titleScreen',false);show('gameoverScreen',false);show('pauseScreen',false);show('upgradeScreen',false);$('hud').style.display='block';updateUI();toast('UNIT LZ-04 DEPLOYED')}
$('startBtn').addEventListener('click',resetGame);$('retryBtn').addEventListener('click',resetGame);$('resumeBtn').addEventListener('click',()=>{paused=false;show('pauseScreen',false)});
